// lab_flame.js 萬用容器
const mySecretCode = "";

const FlameLab = {
    // 開啟全螢幕實驗室
    open: function() {
        if (!document.getElementById('lab-overlay-container')) {
            this.init();
        }
        document.getElementById('lab-overlay-container').style.display = 'flex';
        document.body.style.overflow = 'hidden'; // 鎖定主網頁捲軸
    },

    // 關閉實驗室
    close: function() {
        document.getElementById('lab-overlay-container').style.display = 'none';
        document.body.style.overflow = ''; // 恢復主網頁捲軸
    },

    // 建立實驗室容器
    init: function() {
        const modal = document.createElement('div');
        modal.id = 'lab-overlay-container';
        // 黑色背景遮罩樣式
        modal.style.cssText = "position:fixed; top:0; left:0; width:100%; height:100%; background:#020617; z-index:99999; display:none; flex-direction:column;";
        
        // 浮動關閉按鈕
        const closeBtn = document.createElement('div');
        closeBtn.innerHTML = "✕";
        closeBtn.style.cssText = "position:absolute; top:18px; right:25px; z-index:100000; color:#deb887; border:1.5px solid #deb887; width:34px; height:34px; display:flex; align-items:center; justify-content:center; cursor:pointer; font-family:sans-serif; background:rgba(0,0,0,0.5); border-radius:50%; font-size:16px; box-shadow: 0 0 15px rgba(222, 184, 135, 0.3); transition:0.3s;";
        closeBtn.onmouseover = () => { closeBtn.style.background = "#deb887"; closeBtn.style.color = "#051622"; };
        closeBtn.onmouseout = () => { closeBtn.style.background = "rgba(0,0,0,0.5)"; closeBtn.style.color = "#deb887"; };
        closeBtn.onclick = () => this.close();

        // 建立 Iframe 確保樣式 100% 隔離
        const iframe = document.createElement('iframe');
        iframe.style.cssText = "width:100%; height:100%; border:none; background:#020617;";
        
        // 關鍵：透過 Data URI 載入 Base64 內容
        iframe.src = "data:text/html;charset=utf-8;base64," + mySecretCode;
        
        modal.appendChild(closeBtn);
        modal.appendChild(iframe);
        document.body.appendChild(modal);
        window.addEventListener('message', (e) => {
            if (e.data === 'close-flame-lab') this.close();
        });
    }
};
